window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-781e1823dbe1625f"]={"versions": [{"id": "FIG-781e1823dbe1625f", "releases": ["R2.1.20", "R3.0.7", "R3.1.5", "R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm zeigt das Bit- und Byte-Layout der Protokoll-Kontrollinformation (Protocol Control Information, PCI) für einen Acknowledgement-Frame (ACK-Frame) im FlexRay Transport Layer (AUTOSAR FlexRay AR Transport Layer, FrArTp). Es ordnet die logischen Steuerfelder innerhalb der 4 Byte umfassenden N-PCI auf Feldebene an.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Struktur besteht aus einer zusammenhängenden 4-Byte-PCI-Sequenz mit folgenden Feldern:</p>\n<ul class=\"fig-list\"><li><code>FT</code> (Frame Type): 4 Bit, kennzeichnet den N-PDU-Typ.\n</li><li><code>FS</code> (Flow Status): 4 Bit, steuert den Sendefluss.\n</li><li><code>BS</code> (Block Size): 8 Bit (1 Byte), definiert die Anzahl der aufeinanderfolgenden Consecutive Frames vor der nächsten Bestätigung/Flusskontrolle.\n</li><li><code>STmin</code> (Separation Time minimum): 8 Bit (1 Byte), legt den Mindestabstand zwischen aufeinanderfolgenden Frames fest.\n</li><li><code>ACK</code> (Acknowledgement): 4 Bit, spezifiziert den Quittierungsstatus (z. B. positive oder negative Bestätigung).\n</li><li><code>SN</code> (Sequence Number): 4 Bit, referenziert die Sequenznummer des quittierten Frames.\n</li></ul>\n<p class=\"fig-p\">Über die gesamte Feldanordnung spannt sich eine geschweifte Klammer mit der Gesamtgrößenangabe <code>PCI (4 Byte)</code>. Nutzdatenfelder (Payload/Data) sind in diesem Frame-Format nicht vorhanden.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Acknowledgement-Frame wird vom Empfänger (Receiver) an den Sender (Sender) übertragen, um den Empfang von Datenblöcken zu bestätigen und die Übertragungsparameter (<code>BS</code>, <code>STmin</code>) für nachfolgende Consecutive Frames (CF) zu steuern bzw. zu aktualisieren. Anhand von <code>SN</code> und <code>ACK</code> identifiziert der Sender, bis zu welcher Sequenznummer Datenpakete erfolgreich empfangen oder fehlerhaft gemeldet wurden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Layout ist normativ für die Kodierung und Dekodierung von FrArTp-ACK-Rahmen. Die Gesamtlänge der PCI beträgt exakt 32 Bit (4 Byte). Implementierer müssen die serielle Bit- und Byte-Reihenfolge (Big-Endian-Ausrichtung der FrArTp-N-PDU) gemäß Spezifikation beachten, insbesondere das Zusammenpacken zweier 4-Bit-Felder (<code>FT</code>/<code>FS</code> sowie <code>ACK</code>/<code>SN</code>) in jeweils ein einzelnes Byte (Byte 0 bzw. Byte 3).</p>"}, {"id": "FIG-3565e01696d5a885", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm zeigt das Bit- und Byte-Layout der Protokoll-Kontrollinformation (Protocol Control Information, PCI) für einen Acknowledgement-Frame (ACK-Frame) im FlexRay Transport Layer (AUTOSAR FlexRay AR Transport Layer, FrArTp). Es ordnet die logischen Steuerfelder innerhalb der 4 Byte umfassenden N-PCI auf Feldebene an.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Struktur besteht aus einer zusammenhängenden 4-Byte-PCI-Sequenz mit folgenden Feldern:</p>\n<ul class=\"fig-list\"><li><code>FT</code> (Frame Type): 4 Bit, kennzeichnet den N-PDU-Typ.\n</li><li><code>FS</code> (Flow Status): 4 Bit, steuert den Sendefluss.\n</li><li><code>BS</code> (Block Size): 8 Bit (1 Byte), definiert die Anzahl der aufeinanderfolgenden Consecutive Frames vor der nächsten Bestätigung/Flusskontrolle.\n</li><li><code>STmin</code> (Separation Time minimum): 8 Bit (1 Byte), legt den Mindestabstand zwischen aufeinanderfolgenden Frames fest.\n</li><li><code>ACK</code> (Acknowledgement): 4 Bit, spezifiziert den Quittierungsstatus (z. B. positive oder negative Bestätigung).\n</li><li><code>SN</code> (Sequence Number): 4 Bit, referenziert die Sequenznummer des quittierten Frames.\n</li></ul>\n<p class=\"fig-p\">Über die gesamte Feldanordnung spannt sich eine geschweifte Klammer mit der Gesamtgrößenangabe <code>PCI (4 Byte)</code>. Nutzdatenfelder (Payload/Data) sind in diesem Frame-Format nicht vorhanden.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Acknowledgement-Frame wird vom Empfänger (Receiver) an den Sender (Sender) übertragen, um den Empfang von Datenblöcken zu bestätigen und die Übertragungsparameter (<code>BS</code>, <code>STmin</code>) für nachfolgende Consecutive Frames (CF) zu steuern bzw. zu aktualisieren. Anhand von <code>SN</code> und <code>ACK</code> identifiziert der Sender, bis zu welcher Sequenznummer Datenpakete erfolgreich empfangen oder fehlerhaft gemeldet wurden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Layout ist normativ für die Kodierung und Dekodierung von FrArTp-ACK-Rahmen. Die Gesamtlänge der PCI beträgt exakt 32 Bit (4 Byte). Implementierer müssen die serielle Bit- und Byte-Reihenfolge (Big-Endian-Ausrichtung der FrArTp-N-PDU) gemäß Spezifikation beachten, insbesondere das Zusammenpacken zweier 4-Bit-Felder (<code>FT</code>/<code>FS</code> sowie <code>ACK</code>/<code>SN</code>) in jeweils ein einzelnes Byte (Byte 0 bzw. Byte 3).</p>"}], "trans": [{"from": "FIG-781e1823dbe1625f", "to": "FIG-3565e01696d5a885", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Oberer Bildbereich: Versehentlich mitkopierte Textzeile „[FRTP241] The layout of PCI is shown below.“ oberhalb der Diagrammstruktur enthalten.\n</li></ul>"}, {"from": "FIG-3565e01696d5a885", "to": "FIG-781e1823dbe1625f", "fr": "R3.2.3", "tr": "R4.0.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Oberer Bildbereich: Versehentlich mitkopierte Textzeile „[FRTP241] The layout of PCI is shown below.“ oberhalb der Diagrammstruktur entfernt.\n</li></ul>"}]};
